#!/usr/bin/env python3
"""Reproduce/check the explicit experimental input; never edit release source."""
import hashlib
from pathlib import Path
import subprocess
import sys
import tempfile

profile = Path(__file__).resolve().parents[1]
root = profile.parents[2]
release = root / '.work/source/src/unindent.rs'
destination = root / '.work/adapted'
expected = {
    'Cargo.toml': b'[package]\nname="unindent"\nversion="0.2.4"\nedition="2021"\n[workspace]\n',
    'Cargo.lock': b'# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n[[package]]\nname = "unindent"\nversion = "0.2.4"\n\n[[patch.unused]]\nname = "creusot-std"\nversion = "0.15.0-dev"\n',
}
with tempfile.TemporaryDirectory(dir=root / '.work') as temporary:
    trial = Path(temporary)
    (trial / 'src').mkdir()
    (trial / 'src/unindent.rs').write_bytes(release.read_bytes())
    subprocess.run(['patch', '--batch', '-p1', '-i', str(profile / 'patches/explicit-index.patch')],
                   cwd=trial, check=True, stdout=subprocess.DEVNULL)
    expected['src/lib.rs'] = (trial / 'src/unindent.rs').read_bytes()
assert hashlib.sha256(expected['src/lib.rs']).hexdigest() == (
    'c94193724841424dc9cf020ffb244bf84434a009532f57c28d1c79af65576278')
for name, contents in expected.items():
    path = destination / name
    if '--check' in sys.argv:
        assert path.read_bytes() == contents, f'Adapted source drift: {path}'
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(contents)
print('Experimental source matches the explicit release-derived patch (not formal equivalence).')
